from typing import Dict, List, Sequence, Tuple
from stockflow.first_fit_decreasing import first_fit_decreasing

def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be > 0")
    merged: Dict[str, Tuple[int, int]] = {}
    for sku, qty, weight in lines:
        if qty <= 0 or weight <= 0:
            raise ValueError("qty and unit weight must be > 0")
        if weight > max_parcel_grams:
            raise ValueError(f"Single unit of {sku} exceeds max weight")
        if sku in merged and merged[sku][1] != weight:
            raise ValueError(f"SKU {sku} has inconsistent weights")
        merged[sku] = (merged.get(sku, (0, weight))[0] + qty, weight)
    items = []
    id_map = {}
    cid = 0
    for sku, (qty, weight) in merged.items():
        rem = qty
        while rem > 0:
            chunk = min(rem, max_parcel_grams // weight)
            items.append((str(cid), chunk * weight))
            id_map[str(cid)] = (sku, chunk)
            rem -= chunk
            cid += 1
    bins = first_fit_decreasing(items, max_parcel_grams)
    parcels = []
    for bin_items in bins:
        p = {}
        for cid, w in bin_items:
            sku, q = id_map[cid]
            p[sku] = p.get(sku, 0) + q
        parcels.append(p)
    return parcels"}}}
